// Fetch all JSON API sources.
// Uses $helpers.httpRequest — available in n8n Code nodes (v1+).

const API_SOURCES = [
  // RemoteOK — tag-specific JSON API
  { name: 'remoteok', url: 'https://remoteok.com/api?tags=react' },
  { name: 'remoteok', url: 'https://remoteok.com/api?tags=node' },
  { name: 'remoteok', url: 'https://remoteok.com/api?tags=python' },
  { name: 'remoteok', url: 'https://remoteok.com/api?tags=vue' },
  { name: 'remoteok', url: 'https://remoteok.com/api?tags=flutter' },
  { name: 'remoteok', url: 'https://remoteok.com/api?tags=devops' },
  { name: 'remoteok', url: 'https://remoteok.com/api?tags=typescript' },
  { name: 'remoteok', url: 'https://remoteok.com/api?tags=machine-learning' },
  // Remotive — category JSON API
  { name: 'remotive', url: 'https://remotive.com/api/remote-jobs?category=software-development&limit=100' },
  { name: 'remotive', url: 'https://remotive.com/api/remote-jobs?category=artificial-intelligence&limit=100' },
  { name: 'remotive', url: 'https://remotive.com/api/remote-jobs?category=devops&limit=100' },
  // Jobicy — tag JSON API
  { name: 'jobicy', url: 'https://jobicy.com/api/v2/remote-jobs?industry=dev&tag=react&count=50' },
  { name: 'jobicy', url: 'https://jobicy.com/api/v2/remote-jobs?industry=dev&tag=python&count=50' },
  { name: 'jobicy', url: 'https://jobicy.com/api/v2/remote-jobs?industry=dev&tag=devops&count=50' },
  { name: 'jobicy', url: 'https://jobicy.com/api/v2/remote-jobs?industry=dev&tag=node&count=50' },
  // Himalayas — keyword JSON API
  { name: 'himalayas', url: 'https://himalayas.app/jobs/api/search?q=react&limit=100' },
  { name: 'himalayas', url: 'https://himalayas.app/jobs/api/search?q=python&limit=100' },
  { name: 'himalayas', url: 'https://himalayas.app/jobs/api/search?q=devops&limit=100' },
  // Working Nomads — category JSON API
  { name: 'workingnomads', url: 'https://www.workingnomads.com/api/exposed_jobs/?category=development' },
  // Arbeitnow — remote filter JSON API
  { name: 'arbeitnow', url: 'https://www.arbeitnow.com/api/job-board-api?remote=true' }
];

const apiResults = [];

for (const src of API_SOURCES) {
  try {
    const res = await fetch(src.url, { headers: { 'User-Agent': 'BugsyBot/1.0 (coffey.codes)' } });
    const data = await res.json();
    apiResults.push({ name: src.name, url: src.url, data });
  } catch (e) {
    apiResults.push({ name: src.name, url: src.url, error: e.message });
  }
  await new Promise(r => setTimeout(r, 400));
}

return [{ json: { apiResults } }];

// Fetch all RSS feeds and parse them with a lightweight XML parser.

function extractTag(tag, xml) {
  const cdata = xml.match(new RegExp('<' + tag + '><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\/' + tag + '>'));
  if (cdata) return cdata[1].trim();
  const plain = xml.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\/' + tag + '>'));
  return plain ? plain[1].replace(/<[^>]+>/g, '').trim() : '';
}

function extractLink(xml) {
  const href = xml.match(/<link[^>]+href="([^"]+)"/);
  if (href) return href[1].trim();
  const tag = xml.match(/<link>([^<]*)<\/link>/);
  return tag ? tag[1].trim() : '';
}

function parseRSS(xml, sourceName) {
  const itemRe = /<item[^>]*>([\s\S]*?)<\/item>|<entry[^>]*>([\s\S]*?)<\/entry>/g;
  const jobs = [];
  let m;
  while ((m = itemRe.exec(xml)) !== null) {
    const block = m[1] || m[2];
    jobs.push({
      source: sourceName,
      title: extractTag('title', block),
      link: extractLink(block) || extractTag('guid', block) || extractTag('id', block),
      pubDate: extractTag('pubDate', block) || extractTag('published', block) || extractTag('updated', block),
      description: extractTag('description', block) || extractTag('summary', block) || extractTag('content', block),
      author: extractTag('author', block) || extractTag('dc:creator', block)
    });
  }
  return jobs;
}

const RSS_FEEDS = [
  { name: 'weworkremotely-frontend',  url: 'https://weworkremotely.com/categories/remote-front-end-programming-jobs.rss' },
  { name: 'weworkremotely-backend',   url: 'https://weworkremotely.com/categories/remote-back-end-programming-jobs.rss' },
  { name: 'weworkremotely-fullstack', url: 'https://weworkremotely.com/categories/remote-full-stack-programming-jobs.rss' },
  { name: 'weworkremotely-devops',    url: 'https://weworkremotely.com/categories/remote-devops-sysadmin-jobs.rss' },
  { name: 'remotive-software',        url: 'https://remotive.com/remote-jobs/feed/software-development' },
  { name: 'remotive-ai',              url: 'https://remotive.com/remote-jobs/feed/artificial-intelligence' },
  { name: 'remotive-devops',          url: 'https://remotive.com/remote-jobs/feed/devops' },
  { name: 'remotefirstjobs-react',    url: 'https://remotefirstjobs.com/rss/jobs/react.rss' },
  { name: 'remotefirstjobs-python',   url: 'https://remotefirstjobs.com/rss/jobs/python.rss' },
  { name: 'remotefirstjobs-devops',   url: 'https://remotefirstjobs.com/rss/jobs/devops.rss' },
  { name: 'remotefirstjobs-ai',       url: 'https://remotefirstjobs.com/rss/jobs/ai.rss' },
  { name: 'remotefirstjobs-software', url: 'https://remotefirstjobs.com/rss/jobs/software-development.rss' },
  { name: 'larajobs',                 url: 'https://larajobs.com/feed' },
  { name: 'wordpress-jobs',           url: 'https://jobs.wordpress.net/feed/' },
  { name: 'pyjobs',                   url: 'https://www.pyjobs.com/rss' },
  { name: 'python-org',               url: 'https://www.python.org/jobs/feed/rss/' },
  { name: 'vuejobs',                  url: 'https://app.vuejobs.com/feed/posts' },
  { name: 'authenticjobs',            url: 'https://authenticjobs.com/?feed=job_feed' },
  { name: 'jobspresso',               url: 'https://jobspresso.co/feed/?post_type=job_listing' },
  { name: 'realwork-frontend',        url: 'https://www.realworkfromanywhere.com/remote-frontend-jobs/rss.xml' },
  { name: 'realwork-backend',         url: 'https://www.realworkfromanywhere.com/remote-backend-jobs/rss.xml' },
  { name: 'realwork-devops',          url: 'https://www.realworkfromanywhere.com/remote-devops-and-sysadmin-jobs/rss.xml' },
  { name: 'djangojobboard',           url: 'https://djangojobboard.com/feed/' },
  { name: 'remoteok-react',           url: 'https://remoteok.com/remote-react-jobs.rss' },
  { name: 'remoteok-python',          url: 'https://remoteok.com/remote-python-jobs.rss' },
  { name: 'remoteok-devops',          url: 'https://remoteok.com/remote-devops-jobs.rss' },
  { name: 'jobicy-rss',               url: 'https://jobicy.com/feed/job_feed?job_categories=dev&job_types=full-time' }
];

const rssResults = [];

for (const feed of RSS_FEEDS) {
  try {
    const res = await fetch(feed.url, { headers: { 'User-Agent': 'BugsyBot/1.0 (coffey.codes)', 'Accept': 'application/rss+xml, application/xml, text/xml, */*' } });
    const xml = await res.text();
    const parsed = parseRSS(xml, feed.name);
    rssResults.push(...parsed);
  } catch (e) {
    // Don't let one bad feed kill the run
  }
  await new Promise(r => setTimeout(r, 300));
}

return [{ json: { rssResults } }];

// Normalize all sources to a common schema and filter to Anthony's stack.

const apiResults = $('Fetch API Sources').first().json.apiResults || [];
const rssResults = $('Fetch RSS Sources').first().json.rssResults || [];

const STACK = [
  'react','react native','reactnative','next.js','nextjs',
  'vue','nuxt','angular','flutter','ionic','expo',
  'node','node.js','nodejs','express',
  'python','flask','django','fastapi',
  'php','laravel','wordpress','wp',
  'typescript','javascript',
  'docker','kubernetes','k8s','devops','terraform','ansible','ci/cd','cicd','github actions',
  'aws','gcp','google cloud','firebase','cloud run',
  'postgresql','postgres','mysql','mongodb','redis','firestore','dynamodb',
  'openai','llm','langchain','gemini','ai engineer','ml engineer','machine learning','pytorch','tensorflow','three.js','threejs','webgl',
  'react native','mobile','ios','android'
];

function isRelevant(title, desc) {
  const t = ((title || '') + ' ' + (desc || '')).toLowerCase();
  return STACK.some(kw => t.includes(kw));
}

function extractTags(text) {
  const t = (text || '').toLowerCase();
  return [...new Set(STACK.filter(kw => t.includes(kw)))];
}

function normalizeDate(s) {
  if (!s) return null;
  try { const d = new Date(s); return isNaN(d.getTime()) ? null : d.toISOString(); } catch { return null; }
}

function stripHtml(s) {
  return (s || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 600);
}

const jobs = [];
const seen = new Set();

function add(job) {
  if (!job.url || seen.has(job.url)) return;
  if (!isRelevant(job.title, job.description)) return;
  seen.add(job.url);
  jobs.push({
    source:      job.source || 'unknown',
    title:       (job.title || '').substring(0, 200),
    company:     (job.company || '').substring(0, 100),
    url:         job.url,
    location:    job.location || 'Remote',
    salary_raw:  (job.salary_raw || '').substring(0, 100),
    tech_tags:   extractTags((job.title || '') + ' ' + (job.description || '')),
    description: stripHtml(job.description),
    posted_at:   normalizeDate(job.posted_at)
  });
}

// Process JSON API results
for (const r of apiResults) {
  if (r.error || !r.data) continue;
  const { name, data } = r;

  if (name === 'remoteok') {
    for (const j of (Array.isArray(data) ? data.slice(1) : [])) {
      add({ source:'remoteok', title:j.position||j.title, company:j.company,
        url:j.url||`https://remoteok.com/remote-jobs/${j.id}`,
        salary_raw:j.salary, description:j.description, posted_at:j.date });
    }
  } else if (name === 'remotive') {
    for (const j of (data.jobs || [])) {
      add({ source:'remotive', title:j.title, company:j.company_name,
        url:j.url, salary_raw:j.salary, description:j.description,
        posted_at:j.publication_date });
    }
  } else if (name === 'jobicy') {
    for (const j of (data.jobs || [])) {
      add({ source:'jobicy', title:j.jobTitle, company:j.companyName,
        url:j.url, salary_raw:j.annualSalaryMin?`$${j.annualSalaryMin}-$${j.annualSalaryMax}`:'',
        description:j.jobDescription, posted_at:j.pubDate });
    }
  } else if (name === 'himalayas') {
    for (const j of (data.jobs || [])) {
      add({ source:'himalayas', title:j.title, company:j.company&&j.company.name,
        url:j.applicationLink||`https://himalayas.app/jobs/${j.slug}`,
        description:j.description, posted_at:j.createdAt });
    }
  } else if (name === 'workingnomads') {
    for (const j of (Array.isArray(data)?data:[])) {
      add({ source:'workingnomads', title:j.title, company:j.company,
        url:j.url, description:j.description, posted_at:j.pub_date });
    }
  } else if (name === 'arbeitnow') {
    for (const j of (data.data||[]).filter(j=>j.remote)) {
      add({ source:'arbeitnow', title:j.title, company:j.company_name,
        url:j.url, description:j.description, posted_at:j.created_at });
    }
  }
}

// Process RSS results
for (const item of rssResults) {
  add({ source:item.source, title:item.title, company:item.author,
    url:item.link, description:item.description, posted_at:item.pubDate });
}

return [{ json: { jobs, total: jobs.length } }];

const jobs = $input.first().json.jobs || [];

if (jobs.length === 0) {
  return [{ json: { sql: 'SELECT 1', total: 0 } }];
}

function esc(v) { return String(v||'').replace(/'/g,"''"); }
function escArr(a) {
  if (!a||!a.length) return "'{}'";
  return 'ARRAY[' + a.map(t=>`'${esc(t)}'`).join(',') + ']';
}

const rows = jobs.map(j =>
  `('${esc(j.source)}','${esc(j.title)}','${esc(j.company)}','${esc(j.url)}',` +
  `'${esc(j.location)}','${esc(j.salary_raw)}',${escArr(j.tech_tags)},` +
  `'${esc(j.description)}',${j.posted_at ? `'${j.posted_at}'` : 'NULL'})`
);

const sql =
  'INSERT INTO job_listings (source,title,company,url,location,salary_raw,tech_tags,description,posted_at)\nVALUES\n' +
  rows.join(',\n') +
  '\nON CONFLICT (url) DO NOTHING';

return [{ json: { sql, total: jobs.length } }];

const total = $('Prepare Insert SQL').first().json.total || 0;
const date = new Date().toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
return [{ json: {
  slackText: `📋 *Job Board Sweep — ${date}*\nScraped 30+ niche boards. *${total} new remote jobs* pulled and stored.\nHead to <https://n8n.coffey.codes/webhook/job-board|the board> to browse 'em, skip.`
}}];
